        self._convert_to_shares(assets, Rounding::Floor, erc20)
    }

    /// See [`IErc4626::convert_to_assets`].
    #[allow(clippy::missing_errors_doc)]
    pub fn convert_to_assets(
        &self,
        shares: U256,
        erc20: &Erc20,
