mod tests {
    use crate::test_support::*;
    use alloy_primitives::{uint, Address};
    use stylus_sdk::prelude::*;

    use super::*;
    use crate::{
        token::erc721::{self, extensions::Erc721Metadata, Erc721},
        utils::introspection::erc165::IErc165,
    };
    const TOKEN_ID: U256 = uint!(1_U256);
    use alloy_primitives::aliases::B32;

    #[storage]
    struct Erc721MetadataExample {
        pub erc721: Erc721,
        pub metadata: Erc721Metadata,
        pub uri_storage: Erc721UriStorage,
    }

    #[public]
    #[implements(IErc721Metadata<Error = erc721::Error>, IErc165)]
    impl Erc721MetadataExample {
        #[constructor]
        fn constructor(&mut self, name: String, symbol: String) {
            self.metadata.constructor(name, symbol);
        }

        #[selector(name = "setTokenURI")]
        fn set_token_uri(&mut self, token_id: U256, token_uri: String) {
            self.uri_storage._set_token_uri(token_id, token_uri);
        }
    }

    #[public]
    impl IErc721Metadata for Erc721MetadataExample {
        type Error = erc721::Error;

        fn name(&self) -> String {
            self.metadata.name()
        }

        fn symbol(&self) -> String {
            self.metadata.symbol()
        }

        #[selector(name = "tokenURI")]
        fn token_uri(&self, token_id: U256) -> Result<String, erc721::Error> {
            self.uri_storage.token_uri(token_id, &self.erc721, &self.metadata)
        }
    }

    #[public]
    impl IErc165 for Erc721MetadataExample {
        fn supports_interface(&self, interface_id: B32) -> bool {
            <Self as IErc721Metadata>::interface_id() == interface_id
                || <Self as IErc165>::interface_id() == interface_id
        }
    }

    unsafe impl TopLevelStorage for Erc721MetadataExample {}

    #[openzeppelin_stylus_proc::vm_test]
    fn interface_id() {
        let actual = <Erc721MetadataExample as IErc721Metadata>::interface_id();
        let expected: B32 = 0x5b5e139f_u32.into();
        assert_eq!(actual, expected);
    }

    #[openzeppelin_stylus_proc::vm_test]
    fn supports_interface(
        contract: Contract<Erc721MetadataExample>,
        alice: Address,
    ) {
        assert!(contract.sender(alice).supports_interface(
            <Erc721MetadataExample as IErc721Metadata>::interface_id()
        ));
        assert!(contract.sender(alice).supports_interface(
            <Erc721MetadataExample as IErc165>::interface_id()
        ));

        let fake_interface_id: B32 = 0x12345678_u32.into();
        assert!(!contract.sender(alice).supports_interface(fake_interface_id));
    }
    #[openzeppelin_stylus_proc::vm_test]
    fn token_uri_works(
        contract: Contract<Erc721MetadataExample>,
        alice: Address,
    ) {
        contract
            .sender(alice)
            .erc721
            ._mint(alice, TOKEN_ID)
            .expect("should mint a token for Alice");

        let token_uri = String::from("https://docs.openzeppelin.com/contracts/5.x/api/token/erc721#Erc721URIStorage");
        contract.sender(alice).set_token_uri(TOKEN_ID, token_uri.clone());

        assert_eq!(
            token_uri,
            contract
                .sender(alice)
                .token_uri(TOKEN_ID)
                .expect("should return token URI")
        );
    }

    #[openzeppelin_stylus_proc::vm_test]
    fn token_uri_combines_base_and_stored_suffix_or_token_id(
        contract: Contract<Erc721MetadataExample>,
        alice: Address,
    ) {
        contract
            .sender(alice)
            .erc721
            ._mint(alice, TOKEN_ID)
            .expect("should mint a token for Alice");
        contract
            .sender(alice)
            .metadata
            .base_uri
            .set_str("https://example.test/token/");

        assert_eq!(
            contract.sender(alice).token_uri(TOKEN_ID).unwrap(),
            "https://example.test/token/1"
        );

        let suffix = String::from("metadata.json");
        contract.sender(alice).set_token_uri(TOKEN_ID, suffix.clone());
        assert_eq!(
            contract.sender(alice).token_uri(TOKEN_ID).unwrap(),
            "https://example.test/token/metadata.json"
        );
        contract.assert_emitted(&MetadataUpdate { token_id: TOKEN_ID });
        assert!(contract
            .sender(alice)
            .token_uri(TOKEN_ID + U256::ONE)
            .is_err());
    }

    #[openzeppelin_stylus_proc::vm_test]
    fn token_uri_without_base_returns_stored_uri_or_empty_string(
        contract: Contract<Erc721MetadataExample>,
        alice: Address,
    ) {
        contract
            .sender(alice)
            .erc721
            ._mint(alice, TOKEN_ID)
            .expect("should mint a token for Alice");

        assert_eq!(contract.sender(alice).token_uri(TOKEN_ID).unwrap(), "");

        let stored_uri = String::from("ipfs://metadata");
        contract.sender(alice).set_token_uri(TOKEN_ID, stored_uri.clone());
        assert_eq!(
            contract.sender(alice).token_uri(TOKEN_ID).unwrap(),
            stored_uri
        );
    }
}

