 355	    /// Mints wrapped tokens to cover any underlying tokens that would have been
 356	    /// function that can be exposed with access control if desired.
 357	    ///
 358	    /// # Arguments
 359	    ///
 360	    /// * `&mut self` - Write access to the contract's state.
 361	    /// * `account` - The account to mint tokens to.
 362	    /// * `token_id` - A mutable reference to the Erc20 contract.
 363	    /// * `erc721` - Write access to an [`Erc721`] contract.
 364	    ///
 365	    /// # Errors
 366	    ///
 367	    /// * [`Error::Erc721FailedOperation`] - If the underlying token is not a
 368	    ///   [`Erc721`] contract, or the contract fails to execute the call.
 369	    /// * [`Error::IncorrectOwner`] - If the underlying token is not owned by
 370	    ///   the contract.
 371	    /// * [`Error::InvalidSender`] - If `token_id` already exists.
 372	    /// * [`Error::InvalidReceiver`] - If `to` is [`Address::ZERO`].
 373	    /// * [`Error::InvalidReceiver`] - If
 374	    ///   [`erc721::IErc721Receiver::on_erc721_received`] hasn't returned its
 375	    ///   interface id or returned with an error.
 376	    fn _recover(
 377	        &mut self,
 378	        account: Address,
 379	        token_id: U256,
 380	        erc721: &mut Erc721,
 381	    ) -> Result<U256, Error> {
 382	        let underlying = Erc721Interface::new(self.underlying());
 383	
 384	        let owner = underlying
 385	            .owner_of(self.vm(), Call::new(), token_id)
 386	            .map_err(|_| {
 387	                Error::Erc721FailedOperation(Erc721FailedOperation {
 388	                    token: self.underlying(),
 389	                })
 390	            })?;
 391	
 392	        let contract_address = self.vm().contract_address();
 393	        if owner != contract_address {
 394	            return Err(erc721::Error::IncorrectOwner(
 395	                erc721::ERC721IncorrectOwner {
 396	                    sender: contract_address,
 397	                    token_id,
 398	                    owner,
 399	                },
 400	            )
 401	            .into());
 402	        }
 403	
 404	        erc721._safe_mint(account, token_id, &vec![].into())?;
 405	
 406	        Ok(token_id)
 407	    }
